          let parentSid = ''
          try {
            parentSid = context?.agent?.session?.header?.parentSession || ''
          } catch {}
          if (parentSid && bindings[parentSid]) {
            sid = parentSid
            presetId = getSessionPresetId(sid)
            lastSessionId = sid
          } else {
            return ''
          }
