          var sc = container.querySelector('#tavern-scope-status');
          if (sc) sc.textContent = mode === 'allowlist' ? '白名单模式：默认不吃卡，只有列表的会话生效。' : '全局模式：所有会话都会加载，除下方排除列表。';
          var now = container.querySelector('#tavern-nowcwd');
