      // ★ 收集当前预设的数据（世界书统一用最新状态），供全量保存/数据保存复用
      async function collectSaveState() {
        try {
          var wbSource = state.worldbooks;
          if (typeof wbGroups !== 'undefined' && wbGroups && wbGroups.length) {
            wbSource = wbGroups;
