        }).catch(function (e) {
          clearTimeout(timer);
          status.textContent = '❌ 读取失败：' + (e.name === 'AbortError' ? '超时（会话可能太大或损坏）' : e.message);
        }).finally(function () {
          sessionLoading = false;
          btn.disabled = false;
          btn.textContent = '读取对话';
        });
      });
