// ── 预设元数据管理 ────────────────────────────────────────
function readPresetsMeta() {
  try {
    const raw = fs.readFileSync(PRESETS_META, 'utf8')
    const data = JSON.parse(raw)
    if (!Array.isArray(data.presets)) data.presets = []
    // 兼容旧数据：补全 mode 字段
    data.presets = data.presets.map(p => ({ mode: 'roleplay', ...p }))
