  // 默认预设用旧目录名
  if (presetId === DEFAULT_PRESET_ID) return path.join(ROOT, DEFAULT_PRESET_DIR)
  // ★ 支持 DSH 自带的 agent 预设：直接用预设 ID 作为目录名 ★
  const agentDir = path.join(ROOT, presetId)
  if (fs.existsSync(agentDir)) return agentDir
