          if (summaryMatches && summaryMatches.length > 0) {
            const summaries = summaryMatches.map(s => s.trim()).join('\n\n')
            summaryText = '【📝 对话历史总结（AI 请优先参考此总结，忽略之前的完整对话历史）】\n' + summaries + '\n\n'
