                const sCwd = s.cwd ? String(s.cwd).replace(/[\\/]+$/, '') : ''
                return !sCwd || sCwd === cwdKey
              })
            }
            sessions.sort((a, b) => Number(b.createdAt) - Number(a.createdAt))
